// Headless agent with minimal surface
const options = {
  allowedTools: ["Read", "Glob", "Grep"],
  permissionMode: "dontAsk" // everything else: denied
};

// bypassPermissions with Bash explicitly blocked
// allowed_tools does NOT work for this — you need disallowed_tools
const options = {
  permissionMode: "bypassPermissions",
  disallowedTools: ["Bash"] // guarantees blocking even under bypass
};

{
  "permissions": {
    "allow": ["Read", "Grep"],
    "deny": ["Bash", "Write"],
    "ask": ["Edit"]
  }
}

async function main() {
  const q = query({
    prompt: "Refactor the auth module",
    options: { permissionMode: "plan" } // starts without execution
  });
  // Claude analyzes and proposes — you review the plan
  await q.setPermissionMode("acceptEdits"); // ok, let it edit
  for await (const message of q) {
    if ("result" in message) console.log(message.result);
  }
}

// Two ways to specify a rule
// Tool ← blocks/allows every invocation of the tool
// Tool(specifier) ← blocks/allows only invocations that match

Bash              // every Bash invocation
Bash(npm run build)  // exactly that command
Bash(npm run *)      // any npm run ...
Read(.env)           // read any .env at any depth
Read(/src/**/*.ts)   // read .ts under /src/ relative to project root
WebFetch(domain:api.example.com)  // fetch only to that domain

// * in Bash rules matches any sequence, including spaces
"Bash(npm run *)"      // npm run build, npm run test, npm run dev...
"Bash(* --version)"    // node --version, python --version...
"Bash(git * main)"     // git checkout main, git merge main...

// Critical difference: space before the *
"Bash(ls *)"   // ✓ ls -la  ✗ lsof  ← word boundary from the space
"Bash(ls*)"    // ✓ ls -la  ✓ lsof  ← no boundary

// A trailing :* is equivalent to space + *
"Bash(ls:*)"   // equivalent to "Bash(ls *)"

// The path prefix determines the anchor point:
//   //path  → absolute path from filesystem root
//   ~/path  → relative to the home directory
//   /path   → relative to the project root
//   path    → relative to the current directory

Read(//Users/alice/.ssh/**)  // absolute — double slash
Read(~/.zshrc)               // home
Edit(/src/**/*.ts)           // project root
Read(*.env)                  // current directory

// .env is special: matches at any depth
Read(.env)      // equivalent to Read(**/.env)
Read(//**/.env) // any .env across the whole filesystem

// ⚠️ Trap: Read(/Users/alice/file) is NOT absolute
// It's relative to the project root. For absolute: Read(//Users/alice/file)

{
  "defaultMode": "default",
  "permissions": {
    "allow": [
      "Bash(npm run *)",
      "Bash(git commit *)",
      "Bash(* --version)",
      "WebFetch(domain:api.github.com)"
    ],
    "ask": [
      "Bash(git push *)"
    ],
    "deny": [
      "Bash(rm -rf *)",
      "Bash(curl *)",
      "Read(//**/.env)"
    ]
  }
}

{
  "defaultMode": "dontAsk",
  "permissions": {
    "allow": [
      "Read",
      "Bash(ls *)", "Bash(find * -type f)",
      "Bash(grep *)", "Bash(cat *)",
      "Bash(git log *)", "Bash(git diff *)", "Bash(git status)"
    ],
    "deny": [
      "Edit", "Write",
      "Bash(git commit *)", "Bash(git push *)",
      "Bash(rm *)", "Bash(curl *)", "Bash(wget *)"
    ]
  }
}

{
  "permissions": {
    "allow": [
      "mcp__github__create_issue",
      "mcp__github__list_issues",
      "Agent(Explore)"
    ],
    "deny": [
      "mcp__puppeteer",
      "Agent(Plan)"
    ]
  }
}

{
  "sandbox": {
    "enabled": true,
    "autoAllowBashIfSandboxed": true,
    "failIfUnavailable": false,
    "allowUnsandboxedCommands": true,
    "filesystem": {
      "allowWrite": ["~/.kube", "/tmp"],
      "denyWrite": ["~/.ssh"],
      "denyRead": ["~/.ssh", "~/.aws"],
      "allowRead": ["."]
    },
    "network": {
      "allowedDomains": [
        "registry.npmjs.org",
        "api.github.com"
      ],
      "deniedDomains": ["internal.corp.com"]
    },
    "excludedCommands": ["docker", "watchman"]
  }
}
